import math
import copy
from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

class SuperplyCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    # --- Helper Functions ---

    def _parse_hint(self, hint_str):
        parts = hint_str.split(' ')
        operation = parts[0]
        condition_parts = parts[1:]

        v1 = None
        v2 = None
        condition_type = ""

        try:
            if "less" in condition_parts and "than" in condition_parts:
                condition_type = "is less than v1"
                v1 = int(condition_parts[-1])
            elif "greater" in condition_parts and "than" in condition_parts:
                condition_type = "is greater than v1"
                v1 = int(condition_parts[-1])
            elif "contains" in condition_parts and "digit" in condition_parts:
                condition_type = "contains digit v1"
                v1 = int(condition_parts[-1])
            elif "is" in condition_parts and "even" in condition_parts:
                condition_type = "is even"
            elif "is" in condition_parts and "odd" in condition_parts:
                condition_type = "is odd"
            elif "between" in condition_parts and "and" in condition_parts:
                condition_type = "is between v1 and v2, inclusive"
                # Find the numbers after 'between' and 'and'
                idx_between = condition_parts.index("between")
                idx_and = condition_parts.index("and")
                v1 = int(condition_parts[idx_between + 1])
                v2 = int(condition_parts[idx_and + 1])
        except (ValueError, IndexError):
             # Handle potential errors in parsing hint values
             print(f"Error parsing hint: {hint_str}")
             # Return a function that always returns False if parsing fails
             return lambda r, c: False

        def check(r, c): # r, c are 1-based
            val = 0
            if operation == 'sum':
                val = r + c
            elif operation == 'product':
                val = r * c
            elif operation == 'difference':
                val = abs(r - c)
            else:
                 return False # Invalid operation

            if condition_type == "is less than v1":
                return val < v1
            elif condition_type == "is greater than v1":
                return val > v1
            elif condition_type == "contains digit v1":
                return str(v1) in str(val)
            elif condition_type == "is even":
                return val % 2 == 0
            elif condition_type == "is odd":
                return val % 2 != 0
            elif condition_type == "is between v1 and v2, inclusive":
                # Ensure v1 <= v2 for between condition
                lower = min(v1, v2)
                upper = max(v1, v2)
                return lower <= val <= upper
            else:
                return False # Invalid condition type

        return check

    def _find_valid_moves(self, grid, hint_checker):
        rows = len(grid)
        cols = len(grid[0])
        valid_moves = []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 0: # Check if unoccupied (0-based grid access)
                    # Check hint using 1-based indices
                    if hint_checker(r + 1, c + 1):
                        valid_moves.append((r + 1, c + 1)) # Store 1-based move
        return valid_moves

    def _check_win(self, grid, player_idx):
        rows = len(grid)
        cols = len(grid[0])
        q = collections.deque()
        visited = set()

        # Add starting nodes to the queue and visited set based on player
        if player_idx == 1: # Player 1: Left (col 0) to Right (col cols-1)
            for r in range(rows):
                if grid[r][0] == 1:
                    if (r, 0) not in visited:
                        q.append((r, 0))
                        visited.add((r, 0))
            is_target = lambda r, c: c == cols - 1 # Target column is right edge
        elif player_idx == 2: # Player 2: Top (row 0) to Bottom (row rows-1)
            for c in range(cols):
                if grid[0][c] == 2:
                    if (0, c) not in visited:
                        q.append((0, c))
                        visited.add((0, c))
            is_target = lambda r, c: r == rows - 1 # Target row is bottom edge
        else: # Invalid player index
            return False

        while q:
            r, c = q.popleft()

            # Check if the current node is on the target edge
            # The node itself must be owned by the player (implicit in BFS traversal)
            if is_target(r, c):
                return True

            # Explore neighbors (8 directions: sides and corners)
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue # Skip self
                    nr, nc = r + dr, c + dc

                    # Check if neighbor is within bounds, owned by player, and not visited
                    if 0 <= nr < rows and 0 <= nc < cols and \
                       grid[nr][nc] == player_idx and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))

        # If queue empties and target edge was not reached
        return False

    def _bfs_distance_to_goal(self, grid, start_move, player_idx):
        rows = len(grid)
        cols = len(grid[0])
        # Convert 1-based move to 0-based indices for grid access
        start_r, start_c = start_move[0] - 1, start_move[1] - 1 

        # Basic check for start position validity
        if not (0 <= start_r < rows and 0 <= start_c < cols) or grid[start_r][start_c] != 0:
             return float('inf') # Should not happen if called with a valid move

        q = collections.deque([(start_r, start_c, 0)]) # (row, col, distance)
        visited = set([(start_r, start_c)])

        if player_idx == 1: # Player 1: Target is right edge (col = cols - 1)
            is_target = lambda r, c: c == cols - 1
        elif player_idx == 2: # Player 2: Target is bottom edge (row = rows - 1)
            is_target = lambda r, c: r == rows - 1
        else:
            return float('inf') # Invalid player

        while q:
            r, c, dist = q.popleft()

            # Check if the current cell is on the target edge
            # Path needs to reach the target edge via traversable cells
            if is_target(r, c):
                 # The path length is the number of steps from the start_move
                 # BFS guarantees the first time we hit the target edge gives the shortest path distance
                 return dist

            # Explore neighbors (8 directions)
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc

                    # Check bounds and if neighbor is traversable and not visited
                    if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                        # Path can go through empty cells (0) or cells already owned by player_idx
                        if grid[nr][nc] == 0 or grid[nr][nc] == player_idx:
                            visited.add((nr, nc))
                            q.append((nr, nc, dist + 1))

        # If the queue empties and the target edge was never reached
        return float('inf') 

    # --- Main Logic ---
    def receive_message(self, message: Info) -> Info:
        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]

        rows = len(current_grid)
        cols = len(current_grid[0])
        opponent_idx = 3 - player_idx

        # 1. Parse hint and find valid moves
        hint_checker = self._parse_hint(current_hint)
        valid_moves = self._find_valid_moves(current_grid, hint_checker)

        # Handle case where no valid moves exist (defensive programming)
        if not valid_moves:
             # Fallback: Find the first empty cell satisfying the hint (if any)
             for r_idx in range(rows):
                 for c_idx in range(cols):
                     if current_grid[r_idx][c_idx] == 0:
                         if hint_checker(r_idx + 1, c_idx + 1):
                            return Info(
                                sender=self.__class__.__name__,
                                receiver=message.sender,
                                difficulty=message.difficulty,
                                message=[BaseMessageDataType(data=(r_idx + 1, c_idx + 1), type='custom')]
                            )
             # If still no valid move found (e.g., hint parse error or contradictory state), 
             # return the first empty cell found, even if it violates hint (turn might pass)
             for r_idx in range(rows):
                 for c_idx in range(cols):
                      if current_grid[r_idx][c_idx] == 0:
                           return Info(
                                sender=self.__class__.__name__,
                                receiver=message.sender,
                                difficulty=message.difficulty,
                                message=[BaseMessageDataType(data=(r_idx + 1, c_idx + 1), type='custom')]
                           )
             # If grid is full or other weird state, return (1, 1) as last resort
             return Info(
                 sender=self.__class__.__name__,
                 receiver=message.sender,
                 difficulty=message.difficulty,
                 message=[BaseMessageDataType(data=(1, 1), type='custom')]
             )

        best_move = None
        winning_move = None
        blocking_move = None

        # 2. Check for winning moves
        for move in valid_moves:
            r, c = move[0] - 1, move[1] - 1 # Convert to 0-based index
            # Create a deep copy to avoid modifying the original grid
            temp_grid = [row[:] for row in current_grid] 
            temp_grid[r][c] = player_idx
            if self._check_win(temp_grid, player_idx):
                winning_move = move
                break # Found a winning move, no need to check others

