        for move in valid_moves:
            r, c = move[0] - 1, move[1] - 1 # Convert to 0-based index
            # Create a deep copy
            temp_grid = [row[:] for row in current_grid]
            temp_grid[r][c] = opponent_idx # Simulate opponent playing
            if self._check_win(temp_grid, opponent_idx):
                blocking_move = move
                break # Found a blocking move, prioritize it

        if blocking_move:
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=blocking_move, type='custom')]
            )

        # 4. Heuristic: Choose move closest to the goal edge (BFS distance)
        min_dist = float('inf')
        best_move_heuristic = None
        scored_moves = []

        for move in valid_moves:
             # Calculate shortest path distance from this move to the goal edge
