import re
from collections import deque
from pydantic import BaseModel
from typing import List, Optional, Dict, Any, Tuple
from enum import Enum
from abc import abstractmethod

# Assuming these imports are provided/correct based on the environment
from system.message import Info, BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

# Helper functions (defined globally or could be static methods)
def parse_hint(hint_str: str) -> Dict[str, Any]:
    """Parses the hint string into operation, condition, and values."""
    parts = hint_str.split(' ', 2)
    if len(parts) < 3:
        return {'operation': 'error', 'condition': 'error', 'reason': 'Invalid hint format'}

    operation = parts[0]
    condition_type = parts[1] # 'is' or 'contains'
    condition_details = parts[2]

    parsed = {'operation': operation}

    if operation not in ['sum', 'product', 'difference']:
         parsed['condition'] = 'error'
         parsed['reason'] = f'Invalid operation: {operation}'
         return parsed

    try:
        if condition_type == 'contains':
            match = re.search(r'digit (\d+)', condition_details)
            if match:
                parsed['condition'] = 'contains_digit'
                parsed['v1'] = int(match.group(1))
            else: raise ValueError("Invalid 'contains digit' format")
        elif condition_type == 'is':
            if 'less than' in condition_details:
                match = re.search(r'less than (-?\d+)', condition_details)
                if match:
                    parsed['condition'] = 'less_than'
                    parsed['v1'] = int(match.group(1))
                else: raise ValueError("Invalid 'less than' format")
            elif 'greater than' in condition_details:
                match = re.search(r'greater than (-?\d+)', condition_details)
                if match:
                    parsed['condition'] = 'greater_than'
                    parsed['v1'] = int(match.group(1))
                else: raise ValueError("Invalid 'greater than' format")
            elif 'even' in condition_details:
                parsed['condition'] = 'is_even'
            elif 'odd' in condition_details:
                parsed['condition'] = 'is_odd'
            elif 'between' in condition_details:
                match = re.search(r'between (-?\d+) and (-?\d+), inclusive', condition_details)
                if match:
                    parsed['condition'] = 'between'
                    parsed['v1'] = int(match.group(1))
                    parsed['v2'] = int(match.group(2))
                else: raise ValueError("Invalid 'between' format")
            else:
                 raise ValueError(f"Unknown 'is' condition: {condition_details}")
        else:
