                if current_grid_0_based[r - 1][c - 1] == 0: # Check if empty
                    if self._check_hint_condition(r, c, operation, condition, v1, v2):
                        valid_moves.append((r, c))

        # Handle case where no valid moves exist (rules imply this shouldn't happen if game not over)
        if not valid_moves:
            print(f"Critical Warning: No valid moves found for Player {player_idx} with hint '{current_hint}'. Grid may be full or rules violated.")
            # Fallback: Find *any* empty cell. This violates the hint rule but is a required action.
            first_empty = None
            for r_idx in range(rows):
                for c_idx in range(cols):
                    if current_grid_0_based[r_idx][c_idx] == 0:
                        first_empty = (r_idx + 1, c_idx + 1) # Return 1-based
                        break
                if first_empty: break

            if first_empty:
                position_selected = first_empty
                reasoning = f"Warning: No move satisfies hint '{current_hint}'. Selected first available empty cell {position_selected} as fallback (violates hint rule)."
            else:
                # Grid might be full or another issue
                position_selected = (1, 1) # Final arbitrary fallback if grid is full
                reasoning = "Error: No valid moves found and no empty cells available (Grid Full?). Returning default (1,1)."

            return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=position_selected, type='custom')])

        # 3. Evaluate Valid Moves
        winning_moves = []
        blocking_moves = []
        heuristic_scores = {} # Store scores: {(r, c): score}
        opp_idx = 3 - player_idx

        # Pre-calculate opponent's immediate winning spots (if they could place anywhere empty)
        opponent_winning_spots = set()
        empty_cells_coords = [] # Store 1-based coords of empty cells
        for r_idx in range(rows):
             for c_idx in range(cols):
                 if current_grid_0_based[r_idx][c_idx] == 0:
                     empty_cells_coords.append((r_idx + 1, c_idx + 1))

        for r_opp, c_opp in empty_cells_coords:
             # Use deepcopy for safety, though BFS shouldn't modify grid
             temp_grid = [row[:] for row in current_grid_0_based]
             temp_grid[r_opp - 1][c_opp - 1] = opp_idx # Use 0-based index for grid mutation
             if self._check_win(temp_grid, opp_idx):
                 opponent_winning_spots.add((r_opp, c_opp)) # Store 1-based coord of the winning spot

        # Evaluate each valid move
        for r, c in valid_moves:
            # Calculate Heuristic Score first
            progress_metric = c if player_idx == 1 else r # Progress towards target edge
            connectivity_metric = 0
            r0, c0 = r - 1, c - 1 # 0-based for grid access
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0: continue
                    nr0, nc0 = r0 + dr, c0 + dc
                    if 0 <= nr0 < rows and 0 <= nc0 < cols:
                        if current_grid_0_based[nr0][nc0] == player_idx:
                            connectivity_metric += 1
            # Score: weight progress more heavily
            score = 2 * progress_metric + connectivity_metric
            heuristic_scores[(r, c)] = score

            # Check for Win
            temp_grid_win = [row[:] for row in current_grid_0_based]
            temp_grid_win[r - 1][c - 1] = player_idx # Use 0-based index
            if self._check_win(temp_grid_win, player_idx):
                winning_moves.append((r, c))

            # Check for Block (using the 1-based coordinate)
            if (r, c) in opponent_winning_spots:
                blocking_moves.append((r, c))

        # 4. Select Move based on priority: Win > Block > Heuristic
        if winning_moves:
            # Select the winning move with the highest heuristic score
            best_winner = max(winning_moves, key=lambda move: heuristic_scores.get(move, -1))
            position_selected = best_winner
            reasoning = f"Selected winning move {position_selected} (heuristic score {heuristic_scores.get(best_winner, 'N/A')})."
        elif blocking_moves:
            # Select the blocking move with the highest heuristic score
            best_blocker = max(blocking_moves, key=lambda move: heuristic_scores.get(move, -1))
            position_selected = best_blocker
            reasoning = f"No winning move. Selected blocking move {position_selected} (heuristic score {heuristic_scores.get(best_blocker, -1)})."
        else:
            # No winning or blocking moves, select the move with the best heuristic score
            # Ensure heuristic_scores is not empty (it shouldn't be if valid_moves is not empty)
            if heuristic_scores:
                 # Find the move with the maximum score
                 best_heuristic_move = max(heuristic_scores, key=heuristic_scores.get)
                 best_score = heuristic_scores[best_heuristic_move]
                 position_selected = best_heuristic_move
                 reasoning = f"No winning/blocking move. Selected best heuristic move {position_selected} (score {best_score}) from {len(valid_moves)} valid options."
            else:
                 # Fallback if heuristic scoring somehow failed for all valid moves
                 # This case should ideally not be reached if valid_moves is not empty
                 position_selected = valid_moves[0] # Take the first valid move found
                 reasoning = f"Heuristic evaluation failed for all valid moves. Selected first valid move {position_selected}."

        # Final safety net: ensure a position is selected
        if position_selected is None:
            if valid_moves:
                position_selected = valid_moves[0]
                reasoning = f"Selection logic failed unexpectedly. Selected first valid move {position_selected} as fallback."
            else:
                # This case was handled earlier, but as a failsafe:
                position_selected = (1, 1)
                reasoning = "Critical Error: No valid moves and selection logic failed. Returning default (1,1)."
            print(f"Warning: Position selection reached fallback stage. Reason: {reasoning}")

        # Return the selected position
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

