class SuperplyCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    # --- Helper Functions --- 

    def _parse_hint(self, hint_str: str):
        """ Parses the hint string and returns a checker function. """
        parts = hint_str.strip().split(' ')
        if not parts:
             raise ValueError("Empty hint string")

        operation_str = parts[0]
        condition_str = " ".join(parts[1:])

        # Define operation functions
        def get_value(r, c):
            if operation_str == 'sum':
                return r + c
            elif operation_str == 'product':
                return r * c
            elif operation_str == 'difference':
                return abs(r - c)
            else:
                 raise ValueError(f"Unknown operation: {operation_str}")

        # Define condition checkers
        if 'is less than' in condition_str:
            match = re.search(r'(\d+)', condition_str)
            if not match: raise ValueError(f"Invalid condition format: {condition_str}")
            v1 = int(match.group(1))
            return lambda r, c: get_value(r, c) < v1
        elif 'is greater than' in condition_str:
            match = re.search(r'(\d+)', condition_str)
            if not match: raise ValueError(f"Invalid condition format: {condition_str}")
            v1 = int(match.group(1))
            return lambda r, c: get_value(r, c) > v1
        elif 'contains digit' in condition_str:
            match = re.search(r'(\d+)', condition_str)
            if not match: raise ValueError(f"Invalid condition format: {condition_str}")
            digit = match.group(1)
            return lambda r, c: digit in str(int(get_value(r, c)))
        elif 'is even' in condition_str:
            return lambda r, c: int(get_value(r, c)) % 2 == 0
        elif 'is odd' in condition_str:
            return lambda r, c: int(get_value(r, c)) % 2 != 0
        elif 'is between' in condition_str:
            # Match digits possibly separated by ' and ' or just space
            match = re.search(r'(\d+)\s+(?:and\s+)?(\d+)', condition_str)
            if not match: raise ValueError(f"Invalid condition format: {condition_str}")
            v1 = int(match.group(1))
            v2 = int(match.group(2))
            # Ensure v1 <= v2
            min_v, max_v = min(v1, v2), max(v1, v2)
            return lambda r, c: min_v <= get_value(r, c) <= max_v
        else:
            raise ValueError(f"Unknown condition: {condition_str}")

    def _get_valid_moves(self, grid: List[List[int]], hint_checker) -> List[Tuple[int, int]]:
        """ Finds all unoccupied cells satisfying the hint. """
        valid_moves = []
        if not grid: return [] # Handle empty grid case
        rows = len(grid)
        cols = len(grid[0])
        for r in range(1, rows + 1): # 1-indexed iteration
            for c in range(1, cols + 1): # 1-indexed iteration
                # Check if unoccupied (grid is 0-indexed)
                if 0 <= r-1 < rows and 0 <= c-1 < cols and grid[r-1][c-1] == 0:
                    # Check hint satisfaction
                    try:
                        if hint_checker(r, c):
                            valid_moves.append((r, c))
                    except ValueError as e:
                        print(f"Error checking hint for ({r}, {c}): {e}")
                        continue 
                    except Exception as e:
                        print(f"Unexpected error checking hint for ({r}, {c}): {e}")
                        continue
        return valid_moves

    def _check_win(self, grid: List[List[int]], player_idx: int) -> bool:
        """ Checks if the player has a winning path using BFS. """
        if not grid: return False
        rows = len(grid)
        cols = len(grid[0])
        if rows == 0 or cols == 0: return False

        q = collections.deque()
        visited = set()

        # Initialize queue with starting positions based on player
        if player_idx == 1: # Player 1: Left (col 0) to Right (col cols-1)
            for r in range(rows):
                if grid[r][0] == player_idx:
                    q.append((r, 0))
                    visited.add((r, 0))
        else: # Player 2: Top (row 0) to Bottom (row rows-1)
            for c in range(cols):
                if grid[0][c] == player_idx:
                    q.append((0, c))
                    visited.add((0, c))

        if not q: # No starting cells found
             return False

        # BFS
        while q:
            r, c = q.popleft()

            # Check if target edge reached
            if player_idx == 1 and c == cols - 1:
                return True
            if player_idx == 2 and r == rows - 1:
                return True

            # Explore neighbors (8 directions: sides and corners)
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc

                    # Check bounds
                    if 0 <= nr < rows and 0 <= nc < cols:
                        # Check if neighbor is owned by player and not visited
                        if grid[nr][nc] == player_idx and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
        return False

    def _get_neighbors(self, r: int, c: int, rows: int, cols: int) -> List[Tuple[int, int]]:
        """ Gets valid 0-indexed neighbors for a 0-indexed cell. """
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighbors.append((nr, nc))
        return neighbors

    def _evaluate_move(self, grid: List[List[int]], player_idx: int, r_idx: int, c_idx: int) -> float:
        """ Evaluates a move based on heuristics. Higher score is better. """
        rows = len(grid)
        cols = len(grid[0])
        r0, c0 = r_idx - 1, c_idx - 1 # Convert to 0-indexed
        opponent_idx = 3 - player_idx

        # Heuristic 1: Connectivity to own cells
        connectivity_score = 0
        neighbors = self._get_neighbors(r0, c0, rows, cols)
        for nr, nc in neighbors:
            if grid[nr][nc] == player_idx:
                connectivity_score += 1

        # Heuristic 2: Progress towards target edge
        progress_score = 0
        if player_idx == 1: # P1: Left to Right -> Maximize column c_idx
            progress_score = c_idx / cols
        else: # P2: Top to Bottom -> Maximize row r_idx
            progress_score = r_idx / rows

        # Heuristic 3: Blocking potential (proximity to opponent cells)
        blocking_score = 0
        for nr, nc in neighbors:
            if grid[nr][nc] == opponent_idx:
                blocking_score += 1

        # Heuristic 4: Centrality (distance from center) - lower is better
        center_r, center_c = (rows + 1) / 2.0, (cols + 1) / 2.0
        centrality_dist = math.sqrt((r_idx - center_r)**2 + (c_idx - center_c)**2)
        # Normalize and invert: higher score for being closer to center
        max_dist = math.sqrt(((rows+1)/2.0)**2 + ((cols+1)/2.0)**2) # Approx distance from corner to center
        centrality_score = 1.0 - (centrality_dist / max_dist) if max_dist > 0 else 1.0

        # Combine heuristics with weights (these need tuning)
        w_conn = 2.0
        w_prog = 5.0
        w_block = 1.5 # Weight blocking slightly higher than just connectivity 
        w_cent = 0.5

        total_score = (
            w_conn * connectivity_score +
            w_prog * progress_score +
            w_block * blocking_score +
            w_cent * centrality_score
        )
        return total_score


    # --- Main Logic --- 

    def receive_message(self, message: Info) -> Info:
        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]

        position_selected = None
        if not current_grid:
             # Handle invalid input gracefully
             print("Error: Received empty grid.")
             position_selected = (1, 1)
             return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=position_selected, type='custom')]
            )

        rows = len(current_grid)
        cols = len(current_grid[0])
        opponent_idx = 3 - player_idx

        # 1. Parse the hint
        try:
            hint_checker = self._parse_hint(current_hint)
        except ValueError as e:
            print(f"Error parsing hint '{current_hint}': {e}. Selecting first empty cell.")
            # Fallback: find first empty cell
            for r in range(1, rows + 1):
                for c in range(1, cols + 1):
                    if current_grid[r-1][c-1] == 0:
                         position_selected = (r,c)
                         break
                if position_selected: break
            if not position_selected: position_selected = (1,1) 

            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=position_selected, type='custom')]
            )

        # 2. Find all valid moves
        valid_moves = self._get_valid_moves(current_grid, hint_checker)

        if not valid_moves:
            print(f"Warning: No valid moves found for hint '{current_hint}'. Selecting first empty cell as fallback.")
            fallback_move = None
            for r in range(1, rows + 1):
                for c in range(1, cols + 1):
                    if current_grid[r-1][c-1] == 0:
                        fallback_move = (r, c)
                        break
                if fallback_move: break
            position_selected = fallback_move if fallback_move else (1, 1)

            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=position_selected, type='custom')]
            )

        # 3. Check for winning moves
        winning_move = None
        for r, c in valid_moves:
            temp_grid = copy.deepcopy(current_grid)
            temp_grid[r-1][c-1] = player_idx
            if self._check_win(temp_grid, player_idx):
                winning_move = (r, c)
                # print(f"Debug: Found winning move {winning_move}")
                break

        if winning_move:
            position_selected = winning_move
        else:
            # 4. Check for critical blocking moves
            blocking_move = None
            critical_blocking_moves = []
            for r, c in valid_moves:
                temp_grid = copy.deepcopy(current_grid)
                temp_grid[r-1][c-1] = opponent_idx # Simulate opponent placing here
                if self._check_win(temp_grid, opponent_idx):
                    critical_blocking_moves.append((r, c))

            if critical_blocking_moves:
                 # print(f"Debug: Found critical blocking moves: {critical_blocking_moves}")
                 best_blocking_score = -float('inf')
                 best_blocking_move = None
                 for r_block, c_block in critical_blocking_moves:
                      score = self._evaluate_move(current_grid, player_idx, r_block, c_block)
                      if score > best_blocking_score:
                           best_blocking_score = score
                           best_blocking_move = (r_block, c_block)
                 # Ensure a move is selected if any blocking moves exist
                 blocking_move = best_blocking_move if best_blocking_move else critical_blocking_moves[0]
                 # print(f"Debug: Selected blocking move {blocking_move}")
                 position_selected = blocking_move
            else:
                # 5. No immediate win or critical block, use heuristics
                best_move = None
                best_score = -float('inf')

                # print(f"Debug: Evaluating valid moves: {valid_moves}")
                for r, c in valid_moves:
                    score = self._evaluate_move(current_grid, player_idx, r, c)
                    # print(f"Debug: Score for move ({r},{c}): {score}")
                    if score > best_score:
                        best_score = score
                        best_move = (r, c)

                # Ensure a move is selected if valid moves exist
                if best_move:
                     position_selected = best_move
                else:
                     # Should only happen if all scores are -inf or valid_moves has only one element
                     position_selected = valid_moves[0]
                # print(f"Debug: Selected heuristic move {position_selected}")

        # Final safety check, should ideally never be reached if logic above is sound
        if position_selected is None:
            print("Critical Error: position_selected is None after all checks. Defaulting.")
            position_selected = valid_moves[0] if valid_moves else (1,1) 

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

