class SuperplyCustomStrategy:
    """Implements a custom strategy for the Superply game."""
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        # Ensure history is a list, even if model.history is None or something else
        self.history = getattr(model, 'history', [])
        if not isinstance(self.history, list):
