    def update_model_field(self, field_name: str, value: Any):
        """Updates a field in the underlying model."""
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def _parse_hint(self, hint: str) -> Optional[Dict[str, Any]]:
        """Parses the hint string into operation, condition, and values."""
        parts = hint.lower().split(' ')
        if not parts: return None
        operation = parts[0]
        if operation not in ['sum', 'product', 'difference']: return None # Validate operation

        condition_phrase = " ".join(parts[1:])
        v1 = None
        v2 = None
        condition_key = None

        try:
            if 'between' in condition_phrase and 'and' in condition_phrase:
                between_idx, and_idx = -1, -1
                for i, part in enumerate(parts):
                    if part == 'between': between_idx = i
                    if part == 'and': and_idx = i

                if between_idx != -1 and and_idx != -1 and between_idx < and_idx and between_idx + 1 < len(parts) and and_idx + 1 < len(parts):
                     v1_str = parts[between_idx + 1].rstrip(',.')
                     v2_str = parts[and_idx + 1].rstrip(',.')
                     v1 = int(v1_str)
                     v2 = int(v2_str)
                     condition_key = 'is between v1 and v2, inclusive'
                else: return None 
            elif 'contains digit' in condition_phrase:
                 digit_idx = -1
                 for i, part in enumerate(parts):
                     if part == 'digit': digit_idx = i

                 if digit_idx != -1 and digit_idx + 1 < len(parts):
                     v1_str = parts[digit_idx + 1].rstrip(',.')
                     v1 = int(v1_str)
                     condition_key = 'contains digit v1'
                 else: return None 
            elif 'less than' in condition_phrase:
                 than_idx = -1
                 for i, part in enumerate(parts):
                     if part == 'than': than_idx = i

                 if than_idx > 0 and than_idx + 1 < len(parts) and parts[than_idx-1]=='less': 
                     v1_str = parts[than_idx + 1].rstrip(',.')
                     v1 = int(v1_str)
                     condition_key = 'is less than v1'
                 else: return None 
            elif 'greater than' in condition_phrase:
                 than_idx = -1
                 for i, part in enumerate(parts):
                     if part == 'than': than_idx = i

                 if than_idx > 0 and than_idx + 1 < len(parts) and parts[than_idx-1]=='greater': 
                     v1_str = parts[than_idx + 1].rstrip(',.')
                     v1 = int(v1_str)
                     condition_key = 'is greater than v1'
                 else: return None 
            elif 'is even' in condition_phrase:
                 condition_key = 'is even'
            elif 'is odd' in condition_phrase:
                 condition_key = 'is odd'
            else:
                return None # Unknown format
        except (ValueError, IndexError):
            return None # Parsing error 

        if condition_key is None:
             return None

        return {'operation': operation, 'condition': condition_key, 'v1': v1, 'v2': v2}


    def _check_condition(self, value: int, condition: str, v1: Optional[int], v2: Optional[int]) -> bool:
        """Checks if a value meets a specific condition part."""
        try:
            if condition == 'is less than v1':
                return v1 is not None and value < v1
            elif condition == 'is greater than v1':
                return v1 is not None and value > v1
            elif condition == 'contains digit v1':
                # Ensure v1 is treated as a digit/string for checking presence
                return v1 is not None and str(v1) in str(value)
            elif condition == 'is even':
                return value % 2 == 0
            elif condition == 'is odd':
                return value % 2 != 0
            elif condition == 'is between v1 and v2, inclusive':
                # Ensure v1 and v2 are not None for comparison
                return v1 is not None and v2 is not None and v1 <= value <= v2
        except TypeError: 
             return False
        return False


    def _apply_operation(self, r: int, c: int, operation: str) -> int:
        """Calculates the value based on the operation (using 1-based indices)."""
        if operation == 'sum':
            return r + c
        elif operation == 'product':
            return r * c
        elif operation == 'difference':
            return abs(r - c)
        return -999 # Return an improbable value on error


    def _satisfies_hint(self, r: int, c: int, parsed_hint: Dict) -> bool:
        """Checks if the 1-based position (r, c) satisfies the parsed hint."""
        if parsed_hint is None: return False
