    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        # You can add more instance variables here if needed

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def _parse_hint(self, hint_str: str, N: int, M: int):
        """Parses the hint string and returns a checker function."""
        hint_str = hint_str.lower().strip()
        parts = hint_str.split(' ')

        if not parts or parts == ['']:
            raise ValueError("Empty hint string")

        operation_str = parts[0]
        condition_str = " ".join(parts[1:])

        # Determine operation function
        if operation_str == 'sum':
            op_func = lambda r, c: r + c
        elif operation_str == 'product':
            op_func = lambda r, c: r * c
        elif operation_str == 'difference':
            op_func = lambda r, c: abs(r - c)
        else:
            raise ValueError(f"Unknown operation: {operation_str}")

        # Determine condition function using regex to find numbers
        numbers = [int(d) for d in re.findall(r'\d+', condition_str)]

        if 'is less than' in condition_str:
            if not numbers: raise ValueError(f"Missing value for 'is less than': {condition_str}")
            v1 = numbers[0]
            cond_func = lambda val: val < v1
        elif 'is greater than' in condition_str:
            if not numbers: raise ValueError(f"Missing value for 'is greater than': {condition_str}")
            v1 = numbers[0]
            cond_func = lambda val: val > v1
        elif 'contains digit' in condition_str:
            if not numbers: raise ValueError(f"Missing value for 'contains digit': {condition_str}")
            v1_digit = str(numbers[0])
            cond_func = lambda val: v1_digit in str(val)
        elif 'is even' in condition_str:
            cond_func = lambda val: val % 2 == 0
        elif 'is odd' in condition_str:
            cond_func = lambda val: val % 2 != 0
        elif 'is between' in condition_str and 'and' in condition_str:
            if len(numbers) < 2: raise ValueError(f"Missing values for 'is between': {condition_str}")
            v1, v2 = numbers[0], numbers[1]
            # Ensure v1 <= v2
            if v1 > v2: v1, v2 = v2, v1
            cond_func = lambda val: v1 <= val <= v2
        else:
            raise ValueError(f"Unknown condition: {condition_str}")

        # Combine operation and condition
        checker = lambda r, c: cond_func(op_func(r, c))
        return checker

    def _get_valid_moves(self, grid: List[List[int]], hint_checker, N: int, M: int) -> List[Tuple[int, int]]:
        """Finds all unoccupied cells satisfying the hint."""
        valid_moves = []
        for r in range(1, N + 1):
            for c in range(1, M + 1):
                # Grid is 0-indexed, hint/coords are 1-based
                if grid[r-1][c-1] == 0: # Check if unoccupied
                    try:
                        if hint_checker(r, c): # Check hint
                            valid_moves.append((r, c))
                    except Exception as e:
                        # Log or handle errors during hint checking if necessary
                        # print(f"Debug: Error checking hint for ({r}, {c}): {e}")
                        pass
        return valid_moves

    def _get_neighbors(self, r: int, c: int, N: int, M: int) -> List[Tuple[int, int]]:
        """Gets valid neighbors (1-based) including diagonals."""
        neighbors = []
        # Iterate through offsets for 8 neighbors + center
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue # Skip self
                nr, nc = r + dr, c + dc
                # Check bounds (1-based)
                if 1 <= nr <= N and 1 <= nc <= M:
                    neighbors.append((nr, nc))
        return neighbors

    def _check_win(self, grid: List[List[int]], player_idx: int, N: int, M: int) -> bool:
        """Checks if player_idx has a winning path using BFS."""
        q = deque()
        visited = set()

        if player_idx == 1: # Player 1: Left (col 0) to Right (col M-1)
            for r_idx in range(N):
                if grid[r_idx][0] == player_idx:
                    start_node = (r_idx, 0)
                    q.append(start_node)
                    visited.add(start_node)

            while q:
                r, c = q.popleft()
                if c == M - 1: # Reached right edge
                    return True

                # Explore neighbors (using 0-based grid indices internally)
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0: continue
                        nr, nc = r + dr, c + dc

                        if 0 <= nr < N and 0 <= nc < M and \
                           grid[nr][nc] == player_idx and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))

        elif player_idx == 2: # Player 2: Top (row 0) to Bottom (row N-1)
            for c_idx in range(M):
                if grid[0][c_idx] == player_idx:
                    start_node = (0, c_idx)
                    q.append(start_node)
                    visited.add(start_node)

            while q:
                r, c = q.popleft()
                if r == N - 1: # Reached bottom edge
                    return True

                # Explore neighbors (using 0-based grid indices internally)
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0: continue
                        nr, nc = r + dr, c + dc

                        if 0 <= nr < N and 0 <= nc < M and \
                           grid[nr][nc] == player_idx and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
        else:
            # Invalid player index, should not happen
            return False

        return False # No winning path found

    def receive_message(self, message: Info) -> Info:
        # current_grid is a list of lists of integers (0-based indexing)
        current_grid = message.message[0].data[0]
        # current_hint is a string
        current_hint = message.message[0].data[1]
        # player_idx is an integer: 1 or 2
        player_idx = message.message[0].data[2]
        opponent_idx = 3 - player_idx

        position_selected = None # Stores the final choice (1-based tuple)

        # Get grid dimensions
        if not current_grid or not isinstance(current_grid[0], list) or not current_grid[0]:
            print("Error: Invalid grid received.")
            position_selected = (1, 1)
        else:
            N = len(current_grid)
            M = len(current_grid[0])

            # 1. Parse Hint
            try:
                hint_checker = self._parse_hint(current_hint, N, M)
            except Exception as e:
                print(f"Error parsing hint '{current_hint}': {e}. Returning (1, 1).")
                position_selected = (1, 1)
                # Return immediately if hint parsing fails
                return Info(
                    sender=self.__class__.__name__,
                    receiver=message.sender,
                    difficulty=message.difficulty,
                    message=[BaseMessageDataType(data=position_selected, type='custom')]
                )

            # 2. Find Valid Moves (1-based coordinates)
            valid_moves = self._get_valid_moves(current_grid, hint_checker, N, M)

            if not valid_moves:
                # No valid moves possible according to the hint.
                # Return default (1,1); game engine should handle this (pass turn)
                position_selected = (1, 1)
            else:
                # Create a mutable copy for simulations to avoid altering original grid state during checks
                grid_copy = [row[:] for row in current_grid]

                # 3. Check for Immediate Win
                winning_move = None
                for r, c in valid_moves:
                    grid_copy[r-1][c-1] = player_idx # Simulate move
                    if self._check_win(grid_copy, player_idx, N, M):
                        winning_move = (r, c)
                    grid_copy[r-1][c-1] = 0 # Undo simulation
                    if winning_move:
                        break # Found a winning move

                if winning_move:
                    position_selected = winning_move
                else:
                    # 4. Check for Immediate Block
                    blocking_move = None
                    # Re-use the grid_copy, ensuring it's reset between checks
                    for r, c in valid_moves:
                        # Simulate opponent playing at (r, c) if they could
                        # Cell must be empty for opponent to potentially play there
                        if grid_copy[r-1][c-1] == 0:
                             grid_copy[r-1][c-1] = opponent_idx
                             if self._check_win(grid_copy, opponent_idx, N, M):
                                 blocking_move = (r, c)
                             grid_copy[r-1][c-1] = 0 # Reset cell for next check
                             if blocking_move:
                                 break # Found a blocking move

                    if blocking_move:
                        position_selected = blocking_move
                    else:
                        # 5. Heuristic Evaluation
                        best_move_heuristic = None
                        best_score = -1

                        for r, c in valid_moves:
                            neighbor_score = 0
                            # Use the original grid for evaluating neighbors of current state
                            for nr, nc in self._get_neighbors(r, c, N, M):
                                # Neighbor coords are 1-based, access grid with 0-based
                                if current_grid[nr-1][nc-1] == player_idx:
                                    neighbor_score += 1

                            progress_score = 0
                            if player_idx == 1:
                                progress_score = c # Maximize column index
                            else: # player_idx == 2
                                progress_score = r # Maximize row index

                            # Score: prioritize connections, then progress
                            score = neighbor_score * 10 + progress_score

                            if score > best_score:
                                best_score = score
                                best_move_heuristic = (r, c)
                            elif score == best_score:
                                # Tie-breaking based on progress if connection score is same
                                if best_move_heuristic:
                                    current_progress = progress_score
                                    best_progress = 0
                                    if player_idx == 1:
                                        best_progress = best_move_heuristic[1] # column c
                                    else: # player_idx == 2
                                        best_progress = best_move_heuristic[0] # row r

                                    if current_progress > best_progress:
                                        # This move offers better progress for the same connection score
                                        best_move_heuristic = (r, c)
                                # If progress is also tied, keep the first move found (no change needed)

                        # 6. Select Heuristic Move or Fallback
                        if best_move_heuristic:
                            position_selected = best_move_heuristic
                        elif valid_moves: # Should always be true if heuristic ran
                            # Fallback if heuristic somehow failed (e.g., all scores -1)
                            position_selected = valid_moves[0]
                        # If valid_moves was empty, position_selected is already (1,1)

        # Final safety check ensure position_selected is assigned
        if position_selected is None:
             print("Critical Error: position_selected is None at the end. Defaulting to (1,1).")
             position_selected = (1, 1)

        # Return the selected position (1-based tuple)
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

