# Helper functions
def parse_hint(hint_string: str) -> Tuple[str, str, List[int]]:
    """Parses the hint string into operation, condition, and values."""
    hint_string = hint_string.lower().strip()
    parts = hint_string.split(' ')
    if not parts:
        raise ValueError("Empty hint string")
    operation = parts[0]
    if operation not in ['sum', 'product', 'difference']:
        raise ValueError(f"Unknown operation: {operation}")

    values = [int(s) for s in re.findall(r'\d+', hint_string)] # Find all numbers first

    if "less than" in hint_string:
        condition = "is less than"
    elif "greater than" in hint_string:
        condition = "is greater than"
    elif "contains digit" in hint_string:
        condition = "contains digit"
    elif "is even" in hint_string:
        condition = "is even"
    elif "is odd" in hint_string:
        condition = "is odd"
    elif "between" in hint_string and "and" in hint_string:
        condition = "is between"
        if len(values) == 2:
             values.sort()
        else:
             # Try to extract numbers specifically for 'between' if regex failed
             m = re.search(r'between\s*(\d+)\s*and\s*(\d+)', hint_string)
             if m:
                 values = sorted([int(m.group(1)), int(m.group(2))])
             if len(values) != 2:
                raise ValueError(f"Invalid 'between' hint values: {values} in '{hint_string}'")
    else:
        # Fallback for simple conditions if keywords were potentially missed
        if len(parts) > 1 and parts[1] == 'is':
             if parts[2] == 'even': condition = 'is even'
             elif parts[2] == 'odd': condition = 'is odd'
             else: raise ValueError(f"Unknown condition structure: {hint_string}")
        else:
             raise ValueError(f"Unknown hint format: {hint_string}")

    # Validate number of values based on condition
    if condition in ["is less than", "is greater than", "contains digit"]:
        if len(values) == 0:
             # Attempt to extract digit specifically for 'contains digit'
             m = re.search(r'contains digit\s*(\d)', hint_string)
             if m and condition == "contains digit": values = [int(m.group(1))]
        if len(values) != 1:
            raise ValueError(f"Incorrect number of values for condition '{condition}': {values} in '{hint_string}'")

    if condition == "is between" and len(values) != 2:
         raise ValueError(f"Incorrect number of values for condition 'is between': {values} in '{hint_string}'")

    return operation, condition, values

def check_hint_match(r: int, c: int, operation: str, condition: str, values: List[int]) -> bool:
    """Checks if the 1-based (r, c) matches the parsed hint."""
    val = 0
    if operation == 'sum':
        val = r + c
    elif operation == 'product':
        val = r * c
    elif operation == 'difference':
        val = abs(r - c)
    else:
         return False # Operation validation should prevent this

    try:
        if condition == "is less than":
            return val < values[0]
        elif condition == "is greater than":
            return val > values[0]
        elif condition == "contains digit":
            return str(values[0]) in str(val)
        elif condition == "is even":
            return val % 2 == 0
        elif condition == "is odd":
            return val % 2 != 0
        elif condition == "is between":
            # Values are assumed sorted by parse_hint
            return values[0] <= val <= values[1]
    except IndexError:
        # This occurs if 'values' list is empty or too short for the condition
        # Should ideally be caught by parse_hint validation
        return False 
    return False

def get_neighbors(r: int, c: int, N: int) -> List[Tuple[int, int]]:
    """Gets valid 1-based neighbors (including diagonals) for cell (r, c) on an N x N grid."""
    neighbors = []
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 1 <= nr <= N and 1 <= nc <= N:
                neighbors.append((nr, nc))
    return neighbors

def has_winning_path(grid: List[List[int]], player_idx: int, N: int) -> bool:
    """Checks if player_idx has a winning path on the grid using BFS."""
    if N == 0: return False
    q = deque()
    visited = set()

    # Add starting cells based on player
    if player_idx == 1: # P1: Left to Right
        for r in range(1, N + 1):
            # Check grid index is valid before access: 0 <= r-1 < N and 0 <= 0 < N
            if grid[r-1][0] == player_idx:
                start_node = (r, 1)
                if start_node not in visited:
                    q.append(start_node)
                    visited.add(start_node)
    else: # P2: Top to Bottom
        for c in range(1, N + 1):
             # Check grid index is valid before access: 0 <= 0 < N and 0 <= c-1 < N
             if grid[0][c-1] == player_idx:
                start_node = (1, c)
                if start_node not in visited:
                    q.append(start_node)
                    visited.add(start_node)

    while q:
        curr_r, curr_c = q.popleft()

        if player_idx == 1 and curr_c == N: return True
        if player_idx == 2 and curr_r == N: return True

        for nr, nc in get_neighbors(curr_r, curr_c, N):
            # Check grid index is valid before access: 0 <= nr-1 < N and 0 <= nc-1 < N
            if (nr, nc) not in visited and grid[nr-1][nc-1] == player_idx:
                visited.add((nr, nc))
                q.append((nr, nc))

    return False

