                 return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=position_selected, type='custom')])

            # 2. Find Valid Moves
            valid_moves = []
            for r in range(1, N + 1):
                for c in range(1, N + 1):
                    # Check grid boundaries (0 <= index < N) and if cell is empty (0)
                    if 0 <= r-1 < N and 0 <= c-1 < N and current_grid[r-1][c-1] == 0:
