                             # Catch potential errors in check_hint_match if parse_hint has issues
                             reasoning_steps.append(f"Warning: check_hint_match failed for ({r},{c}) with hint parts: {operation}, {condition}, {values}. Error: {e}")
                             continue # Skip this cell

            reasoning_steps.append(f"Found {len(valid_moves)} valid moves.")

            if not valid_moves:
                reasoning_steps.append("No valid moves found matching the hint.")
                first_empty = None
                for r in range(1, N + 1):
                    for c in range(1, N + 1):
                        if 0 <= r-1 < N and 0 <= c-1 < N and current_grid[r-1][c-1] == 0:
                            first_empty = (r, c)
                            break
                    if first_empty: break

                if first_empty: 
                    position_selected = first_empty
                    reasoning_steps.append(f"Selecting first available empty cell as fallback: {position_selected}")
                else: 
                    # Grid is full, still select default (1,1), game might end anyway
                    reasoning_steps.append(f"Grid appears full. Selecting default fallback: {position_selected}")

                self.reasoning = "\n".join(reasoning_steps)
                return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=position_selected, type='custom')])

            opponent_idx = 3 - player_idx

            # --- Evaluation Steps ---

            # 3. Check for Winning Move
            winning_move = None
            for r, c in valid_moves:
                # Simulate and check win path
                current_grid[r-1][c-1] = player_idx 
                if has_winning_path(current_grid, player_idx, N):
                    winning_move = (r, c)
                current_grid[r-1][c-1] = 0 # Undo simulation
                if winning_move: break

            if winning_move:
                position_selected = winning_move
                reasoning_steps.append(f"Selected winning move: {position_selected}")
                self.reasoning = "\n".join(reasoning_steps)
                return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=position_selected, type='custom')])

            # 4. Check for Blocking Move
            blocking_move = None
            for r, c in valid_moves:
                # Simulate opponent placing *their* piece at this location
                current_grid[r-1][c-1] = opponent_idx 
                if has_winning_path(current_grid, opponent_idx, N):
                     blocking_move = (r, c) # If they would win, I must take this spot
                current_grid[r-1][c-1] = 0 # Undo simulation
                if blocking_move: break 

            if blocking_move:
                position_selected = blocking_move
                reasoning_steps.append(f"Selected blocking move: {position_selected}")
                self.reasoning = "\n".join(reasoning_steps)
                return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=position_selected, type='custom')])

            # 5. Heuristic Scoring for Remaining Moves
            best_move = valid_moves[0] # Default to first valid move if heuristic fails or list is non-empty
            best_score = -float('inf')

            my_pieces = set()
            for r_idx in range(N):
                for c_idx in range(N):
                    # Check bounds just in case grid isn't perfectly square despite earlier checks
                    if 0 <= r_idx < N and 0 <= c_idx < N and current_grid[r_idx][c_idx] == player_idx:
                        my_pieces.add((r_idx + 1, c_idx + 1)) # Use 1-based for set

            W_PROGRESS = 10.0
            W_CONNECT = 5.0 
            W_CENTER = 0.5 

            center_r, center_c = (N + 1) / 2.0, (N + 1) / 2.0

            for r, c in valid_moves:
                score = 0.0

                # Progress Score: Higher means closer to goal edge, normalized
                progress_score = float(c) if player_idx == 1 else float(r)
                score += W_PROGRESS * (progress_score / N) if N > 0 else 0

                # Connection Score: Bonus if adjacent to own piece
                is_adjacent = False
                for nr, nc in get_neighbors(r, c, N):
                    if (nr, nc) in my_pieces:
                        is_adjacent = True
                        break 
                if is_adjacent: score += W_CONNECT 

                # Centrality Score: Bonus for being closer to center
                center_dist = abs(r - center_r) + abs(c - center_c)
                # Max Manhattan distance approx N. Normalize score boost.
                centrality_boost = W_CENTER * (1.0 - center_dist / N) if N > 0 else 0
                score += max(0, centrality_boost) # Add non-negative boost

                if score > best_score:
                    best_score = score
                    best_move = (r, c)
                # Tie-breaking: Implicitly selects the first move with the best score encountered

            position_selected = best_move
            reasoning_steps.append(f"Selected best heuristic move: {position_selected} with score {best_score:.2f}")

        except Exception as e:
            reasoning_steps.append(f"An unexpected error occurred: {type(e).__name__} - {e}.")
            import traceback
            reasoning_steps.append(traceback.format_exc())
            # Use the default position_selected = (1, 1)
            reasoning_steps.append(f"Selecting default fallback move: {position_selected}")

        # Final assembly
        final_reasoning = "\n".join(reasoning_steps) # Use literal \n for JSON output
        self.reasoning = final_reasoning 

        # Return result
        return Info(
