        elif "contains digit" in condition_phrase:
            condition = "contains digit"
        elif "is even" in condition_phrase:
            condition = "is even"
        elif "is odd" in condition_phrase:
            condition = "is odd"
        elif "is between" in condition_phrase:
            condition = "is between"
        else:
            print(f"Warning: Could not parse condition from hint: {hint_str}")
            return operation, None, v1, v2 # Return parsed operation/values but None condition

        return operation, condition, v1, v2

    def _check_cell_condition(self, r: int, c: int, operation: str, condition: str, v1: Optional[int], v2: Optional[int]) -> bool:
        """Checks if the 1-indexed (r, c) satisfies the parsed hint condition."""
