            return v1 is not None and str(v1) in str(value)
        elif condition == 'is even':
            return value % 2 == 0
        elif condition == 'is odd':
            return value % 2 != 0
        elif condition == 'is between':
            # Check v1 and v2 exist before comparison
            return v1 is not None and v2 is not None and v1 <= value <= v2
