class SuperplyCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        # Add any persistent state if needed

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    # --- Helper Methods --- #

    def _parse_hint(self, hint_string: str) -> tuple:
        """Parses the hint string into operation, condition_type, v1, v2."""
        parts = hint_string.strip().split(' ')
        if not parts or len(parts) < 2: raise ValueError(f"Invalid hint string format: {hint_string}")
        operation = parts[0]
        if operation not in ['sum', 'product', 'difference']:
             raise ValueError(f"Unknown operation: {operation}")

        condition_parts = parts[1:]
        condition = " ".join(condition_parts)

        v1, v2 = None, None
        condition_type = None

        # Order matters for matching more specific conditions first
        if 'between' in condition:
            match = re.search(r'between (-?\d+) and (-?\d+)(?:, inclusive)?', condition)
            if match:
                v1 = int(match.group(1))
                v2 = int(match.group(2))
                condition_type = 'between'
        elif 'less than' in condition:
            match = re.search(r'less than (-?\d+)', condition)
            if match:
                v1 = int(match.group(1))
                condition_type = 'less'
        elif 'greater than' in condition:
            match = re.search(r'greater than (-?\d+)', condition)
            if match:
                v1 = int(match.group(1))
                condition_type = 'greater'
        elif 'contains digit' in condition:
            match = re.search(r'contains digit (\d)', condition)
            if match:
                v1 = int(match.group(1)) # v1 is the digit
                condition_type = 'contains_digit'
        elif 'is even' in condition:
            condition_type = 'even'
        elif 'is odd' in condition:
            condition_type = 'odd'

        if condition_type is None:
             raise ValueError(f"Could not parse condition format: {condition}")

        return operation, condition_type, v1, v2

    def _check_hint(self, r: int, c: int, operation: str, condition_type: str, v1: Optional[int], v2: Optional[int]) -> bool:
        """Checks if the 1-based (r, c) satisfies the parsed hint."""
        value = 0
        if operation == 'sum':
            value = r + c
        elif operation == 'product':
            value = r * c
        elif operation == 'difference':
            value = abs(r - c)
        # No else needed due to check in _parse_hint

        try:
            if condition_type == 'less':
                if v1 is None: return False
                return value < v1
            elif condition_type == 'greater':
                if v1 is None: return False
                return value > v1
            elif condition_type == 'contains_digit':
                if v1 is None: return False
                return str(v1) in str(value)
            elif condition_type == 'even':
                return value % 2 == 0
            elif condition_type == 'odd':
                return value % 2 != 0
            elif condition_type == 'between':
                if v1 is None or v2 is None: return False
                # Assume hint ensures v1 <= v2 based on example
                return v1 <= value <= v2
            else:
                return False # Should not happen
        except TypeError: # Catches potential errors comparing value with None
            return False

    def _get_neighbors(self, r: int, c: int, N: int, M: int) -> list:
        """Gets valid 8-directional neighbors for a 0-based (r, c)."""
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < M:
                    neighbors.append((nr, nc))
        return neighbors

    def _check_win(self, grid: List[List[int]], player_idx: int) -> bool:
        """Checks if player_idx has won on the given grid using BFS."""
        N = len(grid)
        if N == 0: return False
        M = len(grid[0])
        if M == 0: return False

        q = deque()
        visited = set()

        if player_idx == 1: # P1: Left (col 0) to Right (col M-1)
            # Handle 1xM grid edge case upfront
            if M == 1:
                for r in range(N):
                     if grid[r][0] == player_idx: return True
                return False
            # Normal BFS start
            for r in range(N):
                if grid[r][0] == player_idx:
                    q.append((r, 0))
                    visited.add((r, 0))
            target_check = lambda r_idx, c_idx: c_idx == M - 1
        elif player_idx == 2: # P2: Top (row 0) to Bottom (row N-1)
            # Handle Nx1 grid edge case upfront
            if N == 1:
                 for c in range(M):
                      if grid[0][c] == player_idx: return True
                 return False
             # Normal BFS start
            for c in range(M):
                if grid[0][c] == player_idx:
                    q.append((0, c))
                    visited.add((0, c))
            target_check = lambda r_idx, c_idx: r_idx == N - 1
        else: # Invalid player index
            return False

        while q:
            r, c = q.popleft()

            if target_check(r, c):
                return True

            for nr, nc in self._get_neighbors(r, c, N, M):
                if grid[nr][nc] == player_idx and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))

        return False # No path found

    def _find_first_valid_move(self, grid: List[List[int]], hint: str, N: int, M: int) -> Optional[Tuple[int, int]]:
         """Fallback: Finds the first unoccupied cell satisfying the hint."""
         try:
             operation, condition_type, v1, v2 = self._parse_hint(hint)
         except ValueError:
             print(f"Fallback failed: Could not parse hint '{hint}'")
             return None

         for r in range(1, N + 1):
             for c in range(1, M + 1):
                 if grid[r - 1][c - 1] == 0: # Unoccupied (0-based access)
                     if self._check_hint(r, c, operation, condition_type, v1, v2): # Check with 1-based coords
                         return (r, c) # Return 1-based coords
         print(f"Fallback failed: No valid unoccupied move found for hint '{hint}'")
         return None

