    def receive_message(self, message: Info) -> Info:
        """Determines the best move based on the current game state and hint."""
        # --- 1. Get Game State --- #
        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]
        opponent_idx = 3 - player_idx

        N = len(current_grid)
        M = len(current_grid[0]) if N > 0 else 0

        if N == 0 or M == 0:
            print("Error: Received empty grid.")
            # Return default (likely invalid) move -> pass turn
            return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=(1, 1), type='custom')])

        position_selected = None

        # --- 2. Parse Hint --- #
        try:
            operation, condition_type, v1, v2 = self._parse_hint(current_hint)
        except ValueError as e:
            print(f"Error parsing hint: {e}. Attempting fallback.")
            position_selected = self._find_first_valid_move(current_grid, current_hint, N, M)
            if position_selected is None:
                print("Fallback failed. Returning default move (1, 1).")
                position_selected = (1, 1)
            return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=position_selected, type='custom')])

        # --- 3. Identify All Valid Moves --- #
        valid_moves = []
        for r in range(1, N + 1):
