            return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=position_selected, type='custom')])

        # --- 4. Check for Winning Moves --- #
        for r, c in valid_moves:
            temp_grid = copy.deepcopy(current_grid)
            temp_grid[r - 1][c - 1] = player_idx # Use 0-based index
            if self._check_win(temp_grid, player_idx):
                position_selected = (r, c) # Return 1-based move
                # print(f"Debug: Found winning move: {position_selected}")
                return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=position_selected, type='custom')])

        # --- 5. Check for Blocking Moves --- #
        blocking_moves = []
        for r, c in valid_moves:
            temp_grid = copy.deepcopy(current_grid)
            temp_grid[r - 1][c - 1] = opponent_idx # Simulate opponent move (0-based index)
            if self._check_win(temp_grid, opponent_idx):
                blocking_moves.append((r, c)) # Store 1-based move

        if blocking_moves:
