            return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=position_selected, type='custom')])

        # --- 6. Strategic Heuristic Move Selection --- #
        scored_moves = []
        for r, c in valid_moves: # Iterate 1-based valid moves
            score = 0.0 # Use float for scores
            friendly_neighbors = 0
            opponent_neighbors = 0

            r0, c0 = r - 1, c - 1 # Convert to 0-based for neighbor checks
            for nr0, nc0 in self._get_neighbors(r0, c0, N, M):
                neighbor_val = current_grid[nr0][nc0]
                if neighbor_val == player_idx:
                    friendly_neighbors += 1
                elif neighbor_val == opponent_idx:
                    opponent_neighbors += 1

            # Score: prioritize connecting to friendly pieces, slightly value blocking
            score += friendly_neighbors * 3.0
            score += opponent_neighbors * 1.0

            # Bonus for progress towards goal (normalized)
            if M > 0 and player_idx == 1: # P1 goal: right edge (col M)
                 score += (c / M) * 2.0
            elif N > 0 and player_idx == 2: # P2 goal: bottom edge (row N)
                 score += (r / N) * 2.0

            scored_moves.append(((r, c), score))

        # Sort moves by score descending
        scored_moves.sort(key=lambda x: x[1], reverse=True)

        if scored_moves:
            position_selected = scored_moves[0][0]
        else:
            # Should not happen if valid_moves is not empty, but use failsafe
            position_selected = valid_moves[0]

