            value = r + c
        elif parsed_hint['operation'] == 'product':
            value = r * c
        elif parsed_hint['operation'] == 'difference':
            value = abs(r - c)

        condition = parsed_hint['condition']
        v1 = parsed_hint['v1']
        v2 = parsed_hint['v2']

        if condition == 'is even':
            return value % 2 == 0
        elif condition == 'is odd':
            return value % 2 != 0
        elif condition == 'is less than':
            # v1 is already int from parsing
            return value < v1
        elif condition == 'is greater than':
            # v1 is already int from parsing
            return value > v1
        elif condition == 'contains digit':
            # v1 is the digit string from parsing
            return str(v1) in str(value)
        elif condition == 'is between':
            # v1 and v2 are already int from parsing
            return v1 <= value <= v2

