def parse_hint(hint_string: str) -> Tuple[str, str, Optional[int], Optional[int]]:
    """Parses the hint string into operation, condition, and values."""
    hint_string = hint_string.lower().strip()
    operation = None
    condition = None
    v1 = None
    v2 = None

    ops = ['sum', 'product', 'difference']
    for op in ops:
