            remainder = hint_string[len(op):].strip()
            break
    else:
         # This case should not happen based on the description format "operation + ' ' + condition"
         raise ValueError(f"Unknown or missing operation in hint: {hint_string}")

    m = re.match(r"is less than (\d+)", remainder)
    if m:
        condition = "is less than"
        v1 = int(m.group(1))
        return operation, condition, v1, None

    m = re.match(r"is greater than (\d+)", remainder)
    if m:
        condition = "is greater than"
        v1 = int(m.group(1))
        return operation, condition, v1, None

    m = re.match(r"contains digit (\d)", remainder)
    if m:
        condition = "contains digit"
        v1 = int(m.group(1))
        return operation, condition, v1, None

    if remainder == "is even":
        condition = "is even"
        return operation, condition, None, None

    if remainder == "is odd":
        condition = "is odd"
        return operation, condition, None, None

    # Added optional comma robustness for 'is between'
    m = re.match(r"is between (\d+) and (\d+),? inclusive", remainder)
    if m:
        condition = "is between"
        v1 = int(m.group(1))
        v2 = int(m.group(2))
