        else: 
            return False # Invalid operation

        try:
            if condition == "is less than":
                return v1 is not None and value < v1
            elif condition == "is greater than":
                return v1 is not None and value > v1
            elif condition == "contains digit":
                # Ensure v1 is treated as a digit (0-9)
                return v1 is not None and 0 <= v1 <= 9 and str(v1) in str(value)
            elif condition == "is even":
                return value % 2 == 0
            elif condition == "is odd":
                return value % 2 != 0
            elif condition == "is between":
                # Ensure v1 and v2 are not None for comparison
                return v1 is not None and v2 is not None and v1 <= value <= v2
            else: 
                return False # Invalid condition
        except TypeError: # Catch potential errors if v1/v2 are None when required
             return False

    def get_neighbors(self, r: int, c: int, N: int) -> List[Tuple[int, int]]:
        ''' Gets valid 8-directional neighbors for a cell (r, c) (0-based) within NxN grid. '''
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    neighbors.append((nr, nc))
        return neighbors

    def check_win(self, grid: List[List[int]], player_idx: int) -> bool:
        ''' Checks if player_idx has a winning path using BFS. '''
        N = len(grid)
        if N == 0: return False
        q = collections.deque()
        visited = set()

        # Initialize queue with starting cells based on player
        if player_idx == 1: # Player 1: Left (col 0) to Right (col N-1)
            for r in range(N):
                if grid[r][0] == player_idx:
                    q.append((r, 0))
                    visited.add((r, 0))
        elif player_idx == 2: # Player 2: Top (row 0) to Bottom (row N-1)
            for c in range(N):
                if grid[0][c] == player_idx:
                    q.append((0, c))
                    visited.add((0, c))
        else:
            return False # Invalid player index

        while q:
            r, c = q.popleft()

            # Check for winning condition
            if player_idx == 1 and c == N - 1:
                return True
            if player_idx == 2 and r == N - 1:
                return True

            # Explore neighbors
            for nr, nc in self.get_neighbors(r, c, N):
                if (nr, nc) not in visited and grid[nr][nc] == player_idx:
                    visited.add((nr, nc))
                    q.append((nr, nc))

        return False # Target edge not reached

    def check_if_move_wins(self, grid: List[List[int]], r: int, c: int, player_idx: int) -> bool:
