    # Helper method to parse the hint string
    def _parse_hint(self, hint_string):
        parts = hint_string.split(' ')
        operation = parts[0] # sum, product, difference

        condition_parts = parts[1:]
        condition_str = " ".join(condition_parts)

        v1 = None
        v2 = None

        # Handle different conditions using regex to find numbers reliably
        if "is less than" in condition_str:
            condition = "is less than v1"
            match = re.search(r'(-?\d+)', condition_str) # Handle potential negative numbers
            if match: v1 = int(match.group(1))
        elif "is greater than" in condition_str:
            condition = "is greater than v1"
            match = re.search(r'(-?\d+)', condition_str)
            if match: v1 = int(match.group(1))
        elif "contains digit" in condition_str:
