            match = re.search(r'(\d)', condition_str) # Only needs a single digit
            if match: v1 = int(match.group(1))
        elif "is even" in condition_str:
            condition = "is even"
        elif "is odd" in condition_str:
            condition = "is odd"
        elif "is between" in condition_str:
            condition = "is between v1 and v2, inclusive"
            nums = re.findall(r'(-?\d+)', condition_str) # Find all numbers
            if len(nums) >= 2:
                 v1 = int(nums[0])
                 v2 = int(nums[1])
                 # Ensure v1 <= v2 for the check logic
                 if v1 > v2: v1, v2 = v2, v1 
        else:
            raise ValueError(f"Unknown condition string format: {condition_str}")

        # Check if values were parsed correctly for conditions that need them
        if condition in ["is less than v1", "is greater than v1", "contains digit v1"] and v1 is None:
             raise ValueError(f"Could not parse value v1 for condition: {condition_str}")
        if condition == "is between v1 and v2, inclusive" and (v1 is None or v2 is None):
             raise ValueError(f"Could not parse values v1/v2 for condition: {condition_str}")

        return operation, condition, v1, v2

    # Helper method to check if a cell (0-indexed r, c) satisfies the hint
    def _check_hint(self, r, c, N, operation, condition, v1, v2):
        row_idx = r + 1 # 1-indexed for hint calculation
        col_idx = c + 1 # 1-indexed for hint calculation

        value = 0
        if operation == 'sum':
            value = row_idx + col_idx
        elif operation == 'product':
            value = row_idx * col_idx
        elif operation == 'difference':
            value = abs(row_idx - col_idx)
        else:
             return False 

        # Check condition
