        except TypeError: # Catches errors if v1/v2 are None
             print(f"Error checking hint condition: {condition} with value {value}, v1={v1}, v2={v2}")
             return False

        return False # Default if condition string is unknown

    # Helper method to check if a player has won using BFS
    def _check_win(self, grid, player_idx):
