                    if dr == 0 and dc == 0: continue

                    nr, nc = r + dr, c + dc

                    # Check bounds and if the neighbor belongs to the player and hasn't been visited
                    if 0 <= nr < N and 0 <= nc < N and \
                       grid[nr][nc] == player_idx and \
                       (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))

