        position_selected = None 

        # 1. Parse Hint
        try:
            operation, condition, v1, v2 = self._parse_hint(current_hint)
        except ValueError as e:
            print(f"Error parsing hint '{current_hint}': {e}")
            # Fallback: Find the first empty cell and return it.
            for r in range(N):
                for c in range(N):
                    if current_grid[r][c] == 0:
                         return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=(r,c), type='custom')])
            # If no empty cells (grid full)
            return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=(0,0), type='custom')])

        # 2. Find Valid Moves according to the hint
        valid_moves = []
        for r in range(N):
