                    if self._check_hint(r, c, N, operation, condition, v1, v2):
                        valid_moves.append((r, c))

        # If no valid moves satisfy the hint
        if not valid_moves:
            print(f"Warning: No valid moves found for player {player_idx} with hint '{current_hint}'. Returning first empty cell as fallback.")
            # Fallback: Return the first empty cell found.
            for r in range(N):
