        if blocking_moves:
            # Prioritize blocking moves. Choose the first one found.
            position_selected = blocking_moves[0]
            return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=position_selected, type='custom')])

        # 5. Heuristic Evaluation (BFS Distance)
        q = collections.deque()
        dist = [[-1] * N for _ in range(N)] # Store distance from start edge
        processed_in_bfs = set() # Track nodes added to queue

