        condition_str = ' '.join(parts[1:])

        ops = {
            'sum': lambda r, c: r + c,
            'product': lambda r, c: r * c,
            'difference': lambda r, c: abs(r - c)
        }
        if operation_str not in ops:
            raise ValueError(f"Unknown operation: {operation_str}")
